PREFIX brick: <http://brickschema.org/brick#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?s ?label WHERE {
  ?s rdfs:label ?label .
  FILTER(CONTAINS(?label, "ZN_6"))
}

PREFIX brick: <http://brickschema.org/brick#>
SELECT ?sensor ?point ?ts WHERE {
  ?sensor a brick:ElectricPowerSensor .
  ?sensor brick:hasLocation ?z .
  FILTER(?z = <http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z07>)
  OPTIONAL { ?sensor brick:hasInput ?in . }
  OPTIONAL { ?point ref:hasExternalReference ?sensor . ?point ref:hasTimeseriesId ?ts . }
}

PREFIX brick: <http://brickschema.org/brick#>
SELECT ?s ?p ?ts WHERE {
  ?s a brick:ElectricPowerSensor .
  FILTER(str(?s) = "http://buildgraph.org/BG_large_office_2004_0000#Electric_Power_Sensor_Z07" || true)
  OPTIONAL { ?point ref:hasExternalReference ?s . ?point ref:hasTimeseriesId ?ts . }
} LIMIT 20

PREFIX brick: <http://brickschema.org/brick#>
SELECT ?s ?pred ?o WHERE {
  ?s a brick:ElectricPowerSensor .
}

PREFIX brick: <http://brickschema.org/brick#>
SELECT (COUNT(*) AS ?c) WHERE {
  ?s a brick:ElectricPowerSensor .
}

PREFIX brick: <http://brickschema.org/brick#>
SELECT DISTINCT ?s WHERE {
  ?s a brick:Sensor .
} LIMIT 20

PREFIX brick: <http://brickschema.org/brick#>
SELECT DISTINCT ?c WHERE {
  ?s a ?c .
  FILTER(CONTAINS(LCASE(str(?c)), "power"))
}

PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?s ?pred ?o WHERE {
  ?s ref:hasTimeseriesId ?ts .
} LIMIT 5

